using System;
using System.IO;
using UnityEditor;
using UnityEngine;
namespace TextureFlow.UnityEditor {
 [Serializable] public class VoidLook {public int style,steps=4;public float yawSpeed=3,depth=.6f,tiling=1,brightness=1,drift=.02f,angle;public bool worldLocked=true;public string tint="#FFFFFF";}
 [Serializable] public class VoidArea {public string name,maskFile,textureFile;public VoidLook look;}
 [Serializable] public class VoidConfig {public int schemaVersion=1;public VoidArea[] areas;}
 [InitializeOnLoad] public static class VoidImporter {
  static double next;
  static VoidImporter(){EditorApplication.update+=Tick;}
  static void Tick(){if(EditorApplication.timeSinceStartup<next||EditorApplication.isCompiling||EditorApplication.isUpdating)return;next=EditorApplication.timeSinceStartup+2;if(!Directory.Exists("Assets/TextureFlow/Exports"))return;foreach(var f in Directory.GetFiles("Assets/TextureFlow/Exports","void-request.json",SearchOption.AllDirectories)){string result=Path.Combine(Path.GetDirectoryName(f),"void-result.json");if(File.Exists(result))continue;try{AssetDatabase.Refresh();string message=Import(f);FlowBridge.WriteJson(result,new FlowReply{success=true,message=message});}catch(Exception ex){FlowBridge.WriteJson(result,new FlowReply{success=false,message=ex.Message});Debug.LogError("Texture Flow void: "+ex);}}}
  static string AssetPath(string folder,string name){if(string.IsNullOrEmpty(name)||Path.IsPathRooted(name))throw new Exception("Invalid area texture path.");string full=Path.GetFullPath(Path.Combine(folder,name));string root=Path.GetFullPath(folder)+Path.DirectorySeparatorChar;if(!full.StartsWith(root,StringComparison.OrdinalIgnoreCase))throw new Exception("Area textures must remain inside the export.");return (folder+"/"+name).Replace('\\','/');}
  static Texture2D Texture(string folder,string file,bool linear,bool repeat){string path=AssetPath(folder,file);var importer=AssetImporter.GetAtPath(path) as TextureImporter;if(importer==null)throw new Exception("Texture not imported: "+path);importer.textureType=TextureImporterType.Default;importer.sRGBTexture=!linear;importer.alphaSource=TextureImporterAlphaSource.FromInput;importer.alphaIsTransparency=false;importer.wrapMode=repeat?TextureWrapMode.Repeat:TextureWrapMode.Clamp;importer.maxTextureSize=8192;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.npotScale=TextureImporterNPOTScale.None;importer.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}

  static void Validate(VoidLook s){bool R(float x,float a,float b){return !float.IsNaN(x)&&!float.IsInfinity(x)&&x>=a&&x<=b;}if(s==null||s.style<0||s.style>2||s.steps<1||s.steps>8||!R(s.yawSpeed,-45,45)||!R(s.depth,.05f,2)||!R(s.tiling,.1f,8)||!R(s.brightness,0,8)||!R(s.drift,-.2f,.2f)||!R(s.angle,0,360)||!ColorUtility.TryParseHtmlString(s.tint,out var unused))throw new Exception("Invalid sky / void settings.");}
  public static string Import(string request){var config=JsonUtility.FromJson<VoidConfig>(File.ReadAllText(request));if(config==null||config.schemaVersion!=1||config.areas==null||config.areas.Length<1||config.areas.Length>8)throw new Exception("Choose one to eight openings.");string dir=Path.GetDirectoryName(request).Replace('\\','/');var original=Texture(dir,"base.png",false,false);var shader=Shader.Find("TextureFlow/Skybox Void");if(shader==null)throw new Exception("Skybox Void shader is missing. Reconnect to update the companion.");var m=new Material(shader);try{m.SetTexture("_MainTex",original);m.SetFloat("_AreaCount",config.areas.Length);for(int i=0;i<config.areas.Length;i++){var a=config.areas[i];if(a==null)throw new Exception("Missing opening.");Validate(a.look);var sky=Texture(dir,a.textureFile,false,true);var mask=Texture(dir,a.maskFile,true,false);if(mask.width!=original.width||mask.height!=original.height)throw new Exception("Opening dimensions do not match the avatar picture.");var s=a.look;ColorUtility.TryParseHtmlString(s.tint,out var tint);m.SetTexture("_Sky"+i,sky);m.SetTexture("_Mask"+i,mask);m.SetVector("_Look"+i,new Vector4(s.style,s.steps,s.depth,s.tiling));m.SetVector("_Motion"+i,new Vector4(s.yawSpeed*Mathf.Deg2Rad,s.angle*Mathf.Deg2Rad,s.drift,s.worldLocked?1:0));m.SetColor("_Tint"+i,tint*s.brightness);}string path=AssetPath(dir,"Void.mat");var existing=AssetDatabase.LoadAssetAtPath<Material>(path);if(existing==null)AssetDatabase.CreateAsset(m,path);else{EditorUtility.CopySerialized(m,existing);UnityEngine.Object.DestroyImmediate(m);m=existing;}EditorUtility.SetDirty(m);AssetDatabase.SaveAssets();return "Created "+config.areas.Length+" independent sky / void opening(s).";}finally{if(m!=null&&!AssetDatabase.Contains(m))UnityEngine.Object.DestroyImmediate(m);}}
 }
}
